function onLoad() {
    var today_date = formatDate(new Date(), 'yyyymmdd').substring(0, 4);
    for (var i = 0; i < 11; i++) {
        g_form.addOption('which_year', parseInt(today_date) - i, parseInt(today_date) - i);
        g_form.setValue('which_year', today_date);
    }

}
